var COMMON_HEADERS=[
 {name:'Content-Type', value:'application/json; charset=utf-8'},
 {name:'Cache-Control', value:'no-store'},
 {name:'Authorization', value:'Bearer <token>'},
 {name:'Accept', value:'application/json'},
 {name:'User-Agent', value:'Mozilla/5.0'},
 {name:'X-Request-Id', value:'<uuid>'},
 {name:'Access-Control-Allow-Origin', value:'*'},
 {name:'Content-Security-Policy', value:"default-src 'self'"}
];
function commonHeaders(){ return COMMON_HEADERS.slice(); }
function parseHeaders(raw){
  var lines=String(raw||'').split(/\r?\n/); var out=[];
  for(var i=0;i<lines.length;i++){
    var L=lines[i]; if(!L.replace(/\s/g,'')) continue;
    var idx=L.indexOf(':'); if(idx<0) continue;
    out.push({name:L.slice(0,idx).replace(/^\s+|\s+$/g,''), value:L.slice(idx+1).replace(/^\s+|\s+$/g,'')});
  }
  return out;
}
function buildHeaders(list){
  var out=[];
  for(var i=0;i<(list||[]).length;i++){ var h=list[i]; if(!h||!h.name) continue; out.push(h.name+': '+h.value); }
  return out.join('\n');
}

var EXPORTS={commonHeaders:commonHeaders,parseHeaders:parseHeaders,buildHeaders:buildHeaders};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HeaderForgePure = EXPORTS; }
